# 長文 レベル1（15文書）
# sentences: (英文, 訳, スラッシュ区切り or None, 文の動詞 or None, 文法項目ID or None)
# questions: type = 目的 / 詳細（ふつうの設問）、言い換え / 精読 / スラッシュ / スキャニング（4つの力）
#   c[0] が正解（ビルド時に並びを混ぜる）。スキャニングは c なしで a = 答えの文の番号（0始まり）
#   ev = 根拠の文の番号、para = 言い換えの対応 [本文の表現, 選択肢の表現]、s = 対象の文の番号

def Q(type, q, c=None, a=0, ev=(), para=(), e='', qj='', s=None):
    return dict(type=type, q=q, c=c, a=a, ev=list(ev), para=[list(p) for p in para], e=e, qj=qj, s=s)

